// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, address caller) public {
        vm.assume(caller != address(this));
        vm.assume(depositAmount > 0);
        vm.assume(withdrawAmount == 0);
        vm.assume(uint256(uint160(caller)) > 100);

        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.addToBalance{value: depositAmount}();

        uint256 balanceBefore = c.getBalance(caller);
        require(balanceBefore == depositAmount, "setup failed");

        vm.prank(caller);
        try c.withdrawBalance() {
            uint256 balanceAfter = c.getBalance(caller);
            assertTrue(balanceAfter == 0);
        } catch {
            assertTrue(true);
        }
    }
}
